#include <vector>
#include <algorithm>

class Solution {
public:
    int longestSubarrayDivKWithOneNegationII(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<int> first_pref(k, 1e9);
        first_pref[0] = -1;

        int running = 0;
        int max_len = 0;

        for (int r = 0; r < n; ++r) {
            running = ((running + nums[r]) % k + k) % k;
            if (first_pref[running] != 1e9) {
                max_len = std::max(max_len, r - first_pref[running]);
            }

            int req = ((running - 2 * nums[r]) % k + k) % k;
            if (first_pref[req] != 1e9) {
                max_len = std::max(max_len, r - first_pref[req]);
            }

            if (first_pref[running] == 1e9) {
                first_pref[running] = r;
            }
        }
        return max_len;
    }
};

